{"query": "
-- ============================================================
-- SMOKE TEST: Verify the trigger correctly blocks bad updates
-- ============================================================

-- Test 1: Try to set num_parts to a wrong value on an existing set
-- This should RAISE an EXCEPTION (we'll catch it by checking pg_exception_detail)
DO $$
DECLARE
    v_set_num TEXT;
    v_current_parts INTEGER;
BEGIN
    -- Pick the first set that has inventory data
    SELECT ls.set_num, ls.num_parts
    INTO v_set_num, v_current_parts
    FROM public.lego_sets ls
    WHERE EXISTS (
        SELECT 1 FROM public.lego_inventories li WHERE li.set_num = ls.set_num
    )
    LIMIT 1;

    BEGIN
        -- Attempt to corrupt the data: set num_parts to an obviously wrong value
        UPDATE public.lego_sets
        SET num_parts = -9999
        WHERE set_num = v_set_num;

        -- If we get here without exception, the trigger failed
        RAISE WARNING 'TRIGGER DID NOT FIRE — consistency check failed for set %', v_set_num;

    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'SUCCESS: Trigger correctly blocked bad update for set %. Error: %', v_set_num, SQLERRM;
    END;
END;
$$;
"}
